  let stream: MediaStream | null = null
  let element: HTMLMediaElement | null = null

  type Fields = { attack: { value: number }; release: { value: number }; bassHz: { value: number }; midHz: { value: number }; trebleHz: { value: number } }
  const makeChannel = (f: Fields) => ({
    ...f,
    level: uniform(0),
    bass: uniform(0),
    mid: uniform(0),
    treble: uniform(0),
    peak: uniform(0),
    beat: uniform(0),
    avg: 0,
    since: Infinity,
  })
  const channels: ReturnType<typeof makeChannel>[] = []

  const band = (rate: number, lo: number, hi: number) => {
    const hz = rate / 2 / BINS
    const a = Math.max(0, Math.floor(lo / hz))
    const b = Math.min(BINS, Math.max(a + 1, Math.ceil(hi / hz)))
    let sum = 0
    for (let i = a; i < b; i++) sum += data[i]
    return sum / (b - a) / 255
  }
  const envelope = (current: number, next: number, dt: number, attack: number, release: number) => {
    const tau = next > current ? attack : release
    return tau <= 0 ? next : current + (next - current) * (1 - Math.exp(-dt / tau))
  }

