          const res = await fetch(from, { credentials: 'omit' })
          const json = (await res.json()) as { columns: string[]; rows: number[][] }
          const n = json.columns.length
          const rows = json.rows.length
          const blocks = Math.ceil(rows / 2048)
          const lines = Math.ceil(rows / blocks)
          const width = n * blocks
